#!/bin/sh
# ODF test documents. They change on every run (dates, random ids), so they are
# not regenerated by this script:
#
# - doc.odt: a Writer document made by LibreOffice from a text file:
#
#     printf 'Hola autofirma-rs\nDocumento de prueba de firma.\n' > doc.txt
#     soffice --headless --convert-to odt doc.txt
#
# - autofirma-rsa.odt: doc.odt signed by AutoFirma 1.9 (AOODFSigner: RSA-SHA1,
#   and the mimetype part deflated and not first):
#
#     J="java -cp /usr/lib/Autofirma/autofirma.jar ../../../tools/AfirmaMulti.java"
#     $J ../certs/rsa.p12 sign odf doc.odt autofirma-rsa.odt
#
# Under the VS Code snap, run java and soffice with a clean environment
# (env -i PATH=/usr/bin:/bin HOME=$HOME ...).
exit 0
